  );
  proof.assignmentReceipt = await receiptFor(
    'task.assign',
    taskId,
    (payload) => payload.owner === 'alice'
  );
  proof.assignmentUiReady = await ui.waitRead(
    desktopTaskBoardAssignmentReadyExpression(options.handleId, taskId, {
      contextId,
      surfaceId,
