        }
        connectionTelemetry.recordRuntimeProviderConnectSuccess({
          runtime: options.runtimeId,
          provider: providerId,
          method,
          intent: connectionAttemptIntent,
          startedAtMs: connectionStartedAtMs,
          verifiedModelId: connectedProvider.verifiedModelId,
