          directorySupported,
          isContextCurrent: () => isProjectContextCurrent(projectContext),
          isRuntimeRevisionCurrent: () => currentRuntimeRevision.current === settledRuntimeRevision,
          refreshExternal: () => options.onProviderChanged?.('connection'),
