              assert.deepEqual(observedScope, scope);
              return work.teamUnavailable;
            },
          };
        },
      }) as Promise<Record<string, unknown> | null>
    );
  return { evaluate, imports, state, detail, controller, storedSession, trigger, triggers, work };
}

